import { Hono } from '../clone/src/hono'
import { HonoRequest } from '../clone/src/request'
import { parseBody as parseBodyMain } from './body-main'

// Monkey-patch so c.req.parseBody() uses the merge-base implementation
;(HonoRequest.prototype as any).parseBody = function (options?: any) {
  return parseBodyMain(this, options)
}

const log = (label: string, v: unknown) => console.log(label, '=>', v)
async function run(label: string, fn: () => Promise<unknown>) {
  try {
    log(label, JSON.stringify(await fn()))
  } catch (e) {
    log(label, `THROWS ${(e as Error).constructor.name}: ${(e as Error).message}`)
  }
}
const multipartReq = () => {
  const fd = new FormData()
  fd.append('message', 'hello')
  return new Request('http://localhost/post', { method: 'POST', body: fd })
}
const urlencodedReq = () => {
  const p = new URLSearchParams()
  p.append('message', 'hello')
  return new Request('http://localhost/post', {
    method: 'POST',
    body: p,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  })
}
await run('A multipart: formData() then parseBody()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.formData()
  return await req.parseBody()
})
await run('B urlencoded: formData() then parseBody()', async () => {
  const req = new HonoRequest(urlencodedReq())
  await req.formData()
  return await req.parseBody()
})
await run('E multipart: text() then parseBody()', async () => {
  const req = new HonoRequest(multipartReq())
  await req.text()
  return await req.parseBody()
})
await run('G multipart: parseBody() then text() equals original', async () => {
  const raw = multipartReq()
  const original = await raw.clone().text()
  const req = new HonoRequest(raw)
  await req.parseBody()
  return (await req.text()) === original
})
await run('H app: middleware formData() then handler parseBody()', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    await c.req.formData()
    await next()
  })
  app.post('/post', async (c) => c.json(await c.req.parseBody()))
  const res = await app.request(multipartReq())
  return { status: res.status, body: await res.text() }
})
EOF
